using System.Globalization;

using JvmBridge.Build.Infrastructure;
using JvmBridge.Build.Models;

namespace JvmBridge.Maintenance;

/// <summary>Writes the pinned JDK inventory as the C# source of <see cref="PinnedJdks"/>, which the build, its tasks and the testing library compile in.</summary>
internal static class PinnedJdkWriter
{
    internal static void Write(string path, int newestJava, IReadOnlyList<JdkEntry> jdks, IReadOnlyList<JdkEntry> legacyJdks)
    {
        List<string> lines =
        [
            "// <auto-generated/>",
            "// Written by `dotnet run --project src/JvmBridge.Maintenance -- update`. Do not edit.",
            string.Empty,
            "namespace JvmBridge.Build.Models;",
            string.Empty,
            "internal static class PinnedJdks",
            "{",
            "    internal const int NewestJava = " + newestJava.ToString(CultureInfo.InvariantCulture) + ";",
            string.Empty,
            "    internal static IReadOnlyList<JdkEntry> Jdks { get; } =",
            "    ["
        ];

        lines.AddRange(jdks.Select(Entry));
        lines.AddRange(["    ];", string.Empty, "    internal static IReadOnlyList<JdkEntry> LegacyJdks { get; } =", "    ["]);
        lines.AddRange(legacyJdks.Select(Entry));
        lines.AddRange(["    ];", "}"]);

        TextFile.Write(path, string.Join(separator: '\n', lines) + "\n");
    }

    private static string Entry(JdkEntry entry)
    {
        List<string> properties = [Text(name: "Rid", entry.Rid), "Java = " + entry.Java.ToString(CultureInfo.InvariantCulture), Text(name: "Implementation", entry.Implementation)];

        foreach (KeyValuePair<string, string?> property in new Dictionary<string, string?>
        {
            [key: "Distribution"] = entry.Distribution,
            [key: "Version"] = entry.Version,
            [key: "Url"] = entry.Url,
            [key: "Sha256"] = entry.Sha256,
            [key: "Status"] = entry.Status,
            [key: "Reason"] = entry.Reason
        })
        {
            if (property.Value is { } value)
                properties.Add(Text(property.Key, value));
        }

        return "        new() { " + string.Join(separator: ", ", properties) + " },";
    }

    private static string Text(string name, string value)
    {
        return name + " = \"" + value.Replace(oldValue: "\\", newValue: "\\\\", StringComparison.Ordinal).Replace(oldValue: "\"", newValue: "\\\"", StringComparison.Ordinal) + "\"";
    }
}
